package com.hatsune.lingolens.common.redis;

import lombok.Getter;

import java.util.Locale;

/**
 * @author hatsune_hitsuzi
 * @since 2026-05-21
 */
@Getter
public enum RedisKeyConstant {

    /**
     * Key: auth:token:{token}
     * Value: {userId}, users.id database primary key.
     * Meaning: maps a login token to the backend user primary key.
     */
    AUTH_TOKEN("auth:token:%s", "{userId}", "login token to users.id mapping"),

    /**
     * Key: lock:user:register:nickname:{nickname}
     * Value: {lockToken}, UUID string generated by RedisDistributedLock.
     * Meaning: prevents concurrent registration with the same nickname.
     */
    USER_REGISTER_NICKNAME_LOCK("lock:user:register:nickname:%s", "{lockToken}", "register nickname lock"),

    /**
     * Key: lock:user:update:nickname:{nickname}
     * Value: {lockToken}, UUID string generated by RedisDistributedLock.
     * Meaning: prevents concurrent profile updates to the same nickname.
     */
    USER_UPDATE_NICKNAME_LOCK("lock:user:update:nickname:%s", "{lockToken}", "update nickname lock"),

    /**
     * Key: id:global:{bizType}
     * Value: Long sequence number.
     * Meaning: global distributed id sequence by business type.
     */
    GLOBAL_ID("id:global:%s", "Long sequence", "global distributed id sequence"),

    /**
     * Key: lock:memory-palace:word:add:{userPkId}:{sceneName}:{wordKey}
     * Value: {lockToken}, UUID string generated by RedisDistributedLock.
     * Meaning: prevents concurrent duplicate adds of the same word into the same user's memory palace scene.
     */
    MEMORY_PALACE_WORD_ADD_LOCK("lock:memory-palace:word:add:%s:%s:%s", "{lockToken}", "memory palace word add lock");

    /**
     * Redis Key 格式，使用 String.format 填充业务参数。
     */
    private final String keyFormat;

    /**
     * Redis Value 格式说明。
     */
    private final String valueFormat;

    /**
     * Redis Key 的业务含义说明。
     */
    private final String description;

    RedisKeyConstant(String keyFormat, String valueFormat, String description) {
        this.keyFormat = keyFormat;
        this.valueFormat = valueFormat;
        this.description = description;
    }

    public String key(Object... args) {
        return String.format(Locale.ROOT, keyFormat, args);
    }
}
